  activity_type = VALUES(activity_type),
  location_scope = VALUES(location_scope),
  place_types = VALUES(place_types),
  dayparts = VALUES(dayparts),
  seasons = VALUES(seasons),
  duration_min = VALUES(duration_min),
  duration_avg = VALUES(duration_avg),
  duration_max = VALUES(duration_max),
  difficulty_physical = VALUES(difficulty_physical),
  difficulty_mental = VALUES(difficulty_mental),
  collaboration = VALUES(collaboration),
  preparation = VALUES(preparation),
  requires_booking = VALUES(requires_booking),
  equipment = VALUES(equipment),
  cost_mxn_pp = VALUES(cost_mxn_pp),
  price_band = VALUES(price_band),
  is_outdoor = VALUES(is_outdoor),
  weather_ok = VALUES(weather_ok),
  ambience = VALUES(ambience),
  description = VALUES(description),
  rationale = VALUES(rationale),
  enriched_by = VALUES(enriched_by),
  confidence = VALUES(confidence),
  reviewed_by = VALUES(reviewed_by),
  needs_review = VALUES(needs_review);
